package dev.hrutvik.filesync.version;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.dao.DuplicateKeyException; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Repository; import java.time.Instant; import java.util.*;
@Repository public class FileVersionStore {
 private final JdbcClient db; private final ObjectMapper json;
 public FileVersionStore(JdbcClient db,ObjectMapper json){this.db=db;this.json=json;}
 public Optional<Head> lockHead(String tenant,String path){return db.sql("select file_id,version,content_hash,size_bytes,deleted,committed_at from file_heads where tenant_id=:t and path=:p for update").param("t",tenant).param("p",path).query((rs,n)->new Head(rs.getObject("file_id",UUID.class),rs.getLong("version"),rs.getString("content_hash"),rs.getLong("size_bytes"),rs.getBoolean("deleted"),rs.getTimestamp("committed_at").toInstant())).optional();}
 public Optional<Head> findHead(String tenant,String path){return db.sql("select file_id,version,content_hash,size_bytes,deleted,committed_at from file_heads where tenant_id=:t and path=:p").param("t",tenant).param("p",path).query((rs,n)->new Head(rs.getObject("file_id",UUID.class),rs.getLong("version"),rs.getString("content_hash"),rs.getLong("size_bytes"),rs.getBoolean("deleted"),rs.getTimestamp("committed_at").toInstant())).optional();}
 public void lockMovePaths(String tenant,String source,String destination){var paths=new ArrayList<>(List.of(source,destination));Collections.sort(paths);for(String path:paths)db.sql("select pg_advisory_xact_lock(hashtextextended(:k,0))").param("k",tenant.length()+":"+tenant+":"+path).query((rs,n)->0).single();}
 public Optional<CommitVersionResponse> replay(String tenant,String operationId,String fingerprint){return db.sql("select file_id,version,path,content_hash,size_bytes,committed_at,request_fingerprint from file_versions where tenant_id=:t and operation_id=:o").param("t",tenant).param("o",operationId).query((rs,n)->{if(!fingerprint.equals(rs.getString("request_fingerprint")))throw new VersionConflictException("operationId was already used with a different request");return new CommitVersionResponse(rs.getObject("file_id",UUID.class),rs.getLong("version"),rs.getString("path"),rs.getString("content_hash"),rs.getLong("size_bytes"),rs.getTimestamp("committed_at").toInstant(),true);}).optional();}
 public CommitVersionResponse save(String tenant,UUID fileId,long version,CommitVersionRequest r,String fingerprint){Instant now=Instant.now();db.sql("insert into file_versions(file_id,tenant_id,version,path,content_hash,size_bytes,device_id,operation_id,request_fingerprint,deleted,committed_at) values(:id,:t,:v,:p,:h,:s,:d,:o,:f,false,:at)").params(Map.of("id",fileId,"t",tenant,"v",version,"p",r.path(),"h",r.contentHash().toLowerCase(Locale.ROOT),"s",r.sizeBytes(),"d",r.deviceId(),"o",r.operationId(),"f",fingerprint,"at",now)).update();upsertHead(tenant,fileId,version,r.path(),r.contentHash().toLowerCase(Locale.ROOT),r.sizeBytes(),false,now);outbox(tenant,fileId,version,"FILE_VERSION_COMMITTED",r.path(),r.contentHash(),false);return new CommitVersionResponse(fileId,version,r.path(),r.contentHash().toLowerCase(Locale.ROOT),r.sizeBytes(),now,false);}
 public CommitVersionResponse tombstone(String tenant,Head head,String path,DeleteFileRequest r,String fingerprint){long version=head.version()+1;Instant now=Instant.now();db.sql("insert into file_versions(file_id,tenant_id,version,path,content_hash,size_bytes,device_id,operation_id,request_fingerprint,deleted,committed_at,change_type) values(:id,:t,:v,:p,:h,0,:d,:o,:f,true,:at,'DELETE')").params(Map.of("id",head.fileId(),"t",tenant,"v",version,"p",path,"h",head.contentHash(),"d",r.deviceId(),"o",r.operationId(),"f",fingerprint,"at",now)).update();upsertHead(tenant,head.fileId(),version,path,head.contentHash(),0,true,now);outbox(tenant,head.fileId(),version,"FILE_DELETED",path,head.contentHash(),true);return new CommitVersionResponse(head.fileId(),version,path,head.contentHash(),0,now,false);}
 public CommitVersionResponse move(String tenant,Head head,String source,String destination,MoveFileRequest r,String fingerprint){long version=head.version()+1;Instant now=Instant.now();Map<String,Object> params=new HashMap<>();params.put("id",head.fileId());params.put("t",tenant);params.put("v",version);params.put("p",destination);params.put("h",head.contentHash());params.put("s",head.sizeBytes());params.put("d",r.deviceId());params.put("o",r.operationId());params.put("f",fingerprint);params.put("at",now);params.put("previous",source);db.sql("insert into file_versions(file_id,tenant_id,version,path,content_hash,size_bytes,device_id,operation_id,request_fingerprint,deleted,committed_at,change_type,previous_path) values(:id,:t,:v,:p,:h,:s,:d,:o,:f,false,:at,'MOVE',:previous)").params(params).update();db.sql("delete from file_heads where tenant_id=:t and path=:p").param("t",tenant).param("p",source).update();upsertHead(tenant,head.fileId(),version,destination,head.contentHash(),head.sizeBytes(),false,now);outbox(tenant,head.fileId(),version,"FILE_MOVED",destination,head.contentHash(),false,source);return new CommitVersionResponse(head.fileId(),version,destination,head.contentHash(),head.sizeBytes(),now,false);}
 private void upsertHead(String t,UUID id,long v,String p,String h,long s,boolean deleted,Instant at){db.sql("insert into file_heads(tenant_id,path,file_id,version,content_hash,size_bytes,deleted,committed_at) values(:t,:p,:id,:v,:h,:s,:x,:at) on conflict(tenant_id,path) do update set file_id=excluded.file_id,version=excluded.version,content_hash=excluded.content_hash,size_bytes=excluded.size_bytes,deleted=excluded.deleted,committed_at=excluded.committed_at").params(Map.of("t",t,"p",p,"id",id,"v",v,"h",h,"s",s,"x",deleted,"at",at)).update();}
 private void outbox(String t,UUID id,long v,String type,String path,String hash,boolean deleted){outbox(t,id,v,type,path,hash,deleted,null);}
 private void outbox(String t,UUID id,long v,String type,String path,String hash,boolean deleted,String previousPath){try{Map<String,Object> event=new LinkedHashMap<>();event.put("fileId",id);event.put("version",v);event.put("path",path);event.put("contentHash",hash);event.put("deleted",deleted);if(previousPath!=null)event.put("previousPath",previousPath);String payload=json.writeValueAsString(event);db.sql("insert into outbox_events(id,tenant_id,aggregate_id,event_type,payload,created_at) values(:id,:t,:a,:e,cast(:p as jsonb),now())").params(Map.of("id",UUID.randomUUID(),"t",t,"a",id,"e",type,"p",payload)).update();}catch(JsonProcessingException e){throw new IllegalStateException(e);}}
 public record Head(UUID fileId,long version,String contentHash,long sizeBytes,boolean deleted,Instant committedAt){}
}
